using System;
using System.Collections.Concurrent;
using System.IO;
using System.Net.WebSockets;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace ChatServer
{
    public class UploadChunkProcessor
    {
        private readonly ConcurrentDictionary<string, UploadSession> _sessions = new();
        private const int MaxFileSize = 50 * 1024 * 1024; // 50MB
        private const int MaxChunkSize = 64 * 1024; // 64KB

        public class UploadSession
        {
            public string SessionId { get; set; }
            public string FileName { get; set; }
            public int TotalSize { get; set; }
            public int ReceivedBytes { get; set; }
            public MemoryStream Buffer { get; set; }
            public DateTime StartedAt { get; set; }
            public int ChunkCount { get; set; }
        }

        public async Task<string> InitiateUpload(string userId, string fileName, int totalSize)
        {
            if (totalSize <= 0 || totalSize > MaxFileSize)
                throw new ArgumentException("Invalid file size");

            if (string.IsNullOrWhiteSpace(fileName) || fileName.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0)
                throw new ArgumentException("Invalid file name");

            // Validate userId: it becomes part of the SessionId which is later used
            // to build the stored file path. Reject anything that is not a simple
            // alphanumeric identifier to prevent path traversal.
            if (string.IsNullOrWhiteSpace(userId))
                throw new ArgumentException("Invalid user id");
            foreach (var c in userId)
            {
                if (!char.IsLetterOrDigit(c) && c != '-')
                    throw new ArgumentException("Invalid user id");
            }

            var sessionId = GenerateSessionId(userId);
            var session = new UploadSession
            {
                SessionId = sessionId,
                FileName = fileName,
                TotalSize = totalSize,
                ReceivedBytes = 0,
                Buffer = new MemoryStream(totalSize),
                StartedAt = DateTime.UtcNow,
                ChunkCount = 0
            };

            _sessions[sessionId] = session;
            return sessionId;
        }

        public async Task<UploadResult> ProcessChunk(string sessionId, byte[] chunkData, int chunkIndex)
        {
            if (!_sessions.TryGetValue(sessionId, out var session))
                throw new InvalidOperationException("Session not found");

            if (chunkData == null || chunkData.Length == 0)
                throw new ArgumentException("Empty chunk");

            if (chunkData.Length > MaxChunkSize)
                throw new ArgumentException("Chunk exceeds maximum size");

            // Calculate the expected offset for this chunk
            long expectedOffset = ComputeChunkOffset(chunkIndex, chunkData.Length);

            // Validate we haven't exceeded total size
            int newTotal = session.ReceivedBytes + chunkData.Length;
            if (newTotal > session.TotalSize)
                throw new InvalidOperationException("Upload exceeds declared size");

            // Validate offset is within bounds
            if (expectedOffset < 0 || expectedOffset + chunkData.Length > session.TotalSize)
                throw new InvalidOperationException("Chunk offset out of bounds");

            // Write chunk at the computed offset
            session.Buffer.Position = expectedOffset;
            await session.Buffer.WriteAsync(chunkData, 0, chunkData.Length);
            session.ReceivedBytes = newTotal;
            session.ChunkCount++;

            if (session.ReceivedBytes == session.TotalSize)
            {
                return await FinalizeUpload(session);
            }

            return new UploadResult { Complete = false, BytesReceived = session.ReceivedBytes };
        }

        private long ComputeChunkOffset(int chunkIndex, int chunkSize)
        {
            // Use long arithmetic to prevent overflow
            // Each chunk is placed at chunkIndex * chunkSize
            return (long)chunkIndex * (long)chunkSize;
        }

        private async Task<UploadResult> FinalizeUpload(UploadSession session)
        {
            var data = session.Buffer.ToArray();
            var hash = ComputeHash(data);

            string uploadsDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "uploads");
            Directory.CreateDirectory(uploadsDir);

            string fileName = $"{session.SessionId}_{session.FileName}";
            string safePath = Path.Combine(uploadsDir, fileName);

            // Defense in depth: ensure the resolved path stays inside the uploads directory
            string fullUploadsDir = Path.GetFullPath(uploadsDir + Path.DirectorySeparatorChar);
            string fullSafePath = Path.GetFullPath(safePath);
            if (!fullSafePath.StartsWith(fullUploadsDir, StringComparison.Ordinal))
                throw new InvalidOperationException("Resolved path escapes uploads directory");

            await File.WriteAllBytesAsync(fullSafePath, data);

            _sessions.TryRemove(session.SessionId, out _);
            session.Buffer.Dispose();

            return new UploadResult
            {
                Complete = true,
                BytesReceived = session.ReceivedBytes,
                FileHash = hash,
                StoredPath = fullSafePath
            };
        }

        private string ComputeHash(byte[] data)
        {
            using var sha = SHA256.Create();
            var hashBytes = sha.ComputeHash(data);
            return Convert.ToHexString(hashBytes);
        }

        private string GenerateSessionId(string userId)
        {
            using var rng = RandomNumberGenerator.Create();
            var bytes = new byte[16];
            rng.GetBytes(bytes);
            return $"{userId}_{Convert.ToHexString(bytes)}";
        }
    }

    public class UploadResult
    {
        public bool Complete { get; set; }
        public int BytesReceived { get; set; }
        public string FileHash { get; set; }
        public string StoredPath { get; set; }
    }

    public class ChatWebSocketHandler
    {
        private readonly UploadChunkProcessor _processor = new();

        public async Task HandleUploadMessage(WebSocket socket, byte[] message)
        {
            // Protocol: [1 byte type][4 bytes sessionId length][sessionId][4 bytes chunkIndex][chunk data]
            if (message.Length < 9)
                return;

            byte msgType = message[0];
            if (msgType == 0x01) // Initiate
            {
                // Parse initiation request
                var payload = Encoding.UTF8.GetString(message, 1, message.Length - 1);
                var parts = payload.Split('|');
                if (parts.Length == 3 && int.TryParse(parts[2], out int size))
                {
                    var sid = await _processor.InitiateUpload(parts[0], parts[1], size);
                    var response = Encoding.UTF8.GetBytes($"OK|{sid}");
                    await socket.SendAsync(response, WebSocketMessageType.Binary, true, CancellationToken.None);
                }
            }
            else if (msgType == 0x02) // Chunk
            {
                int sidLen = BitConverter.ToInt32(message, 1);
                if (sidLen <= 0 || sidLen > 256 || 5 + sidLen + 4 > message.Length)
                    return;

                string sessionId = Encoding.UTF8.GetString(message, 5, sidLen);
                int chunkIndex = BitConverter.ToInt32(message, 5 + sidLen);

                if (chunkIndex < 0)
                    return;

                int dataOffset = 5 + sidLen + 4;
                int dataLen = message.Length - dataOffset;
                byte[] chunkData = new byte[dataLen];
                Array.Copy(message, dataOffset, chunkData, 0, dataLen);

                var result = await _processor.ProcessChunk(sessionId, chunkData, chunkIndex);
                var resp = Encoding.UTF8.GetBytes($"CHUNK|{result.BytesReceived}|{result.Complete}");
                await socket.SendAsync(resp, WebSocketMessageType.Binary, true, CancellationToken.None);
            }
        }
    }
}
